INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist jedes Projekt nach DIN 69901 zeitlich befristet?', 2, '[{"text": "Ja", "correct": true, "because": "Zeitliche Begrenzung ist ein Kernmerkmal"}, {"text": "Nein", "correct": false, "because": "Dauerhaftigkeit ist nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt "zeitlich befristet" am besten?', 3, '[{"text": "Fester Start- und Endtermin", "correct": true, "because": "Definiert die Begrenzung"}, {"text": "Unendliche Laufzeit", "correct": false, "because": "Widerspricht dem Merkmal"}, {"text": "Flexible Teamgröße", "correct": false, "because": "Unabhängig von Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zeitliche Befristung bedeutet klar definierte Deadlines. b) Projekte können ohne Ende laufen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht der Definition"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zentral"}, {"text": "Beides falsch", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zur zeitlichen Befristung?', 4, '[{"text": "Projektphasen mit Terminen", "correct": true, "because": "Strukturieren die Zeit"}, {"text": "Unbegrenzte Verlängerung", "correct": false, "because": "Widerspricht Befristung"}, {"text": "Meilensteine", "correct": true, "because": "Markieren Zeitpunkte"}, {"text": "Keine Zeitvorgaben", "correct": false, "because": "Fehlt Begrenzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne festen Endtermin zeitlich befristet sein?', 2, '[{"text": "Nein", "correct": true, "because": "Ende muss definiert sein"}, {"text": "Ja", "correct": false, "because": "Widerspricht der Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt die zeitliche Befristung?', 3, '[{"text": "Zeitplan", "correct": true, "because": "Legt Termine fest"}, {"text": "Teamliste", "correct": false, "because": "Unabhängig von Zeit"}, {"text": "Budgetplan", "correct": false, "because": "Fokussiert Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine tägliche Aufgabe zeitlich befristet?', 2, '[{"text": "Nein", "correct": true, "because": "Wiederholung fehlt Projektmerkmal"}, {"text": "Ja", "correct": false, "because": "Routine ist nicht befristet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz hat die zeitliche Befristung?', 3, '[{"text": "Druck zur Einhaltung von Terminen", "correct": true, "because": "Zeit ist begrenzt"}, {"text": "Unendliche Verfügbarkeit", "correct": false, "because": "Widerspricht Befristung"}, {"text": "Keine Planung nötig", "correct": false, "because": "Planung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zeitliche Befristung erhöht den Planungsaufwand. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist ein Muss-Merkmal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört nicht zur zeitlichen Befristung?', 2, '[{"text": "Offene Laufzeit", "correct": true, "because": "Widerspricht der Definition"}, {"text": "Definierter Projektstart", "correct": false, "because": "Teil der Befristung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein zeitlich befristetes Projekt verlängert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassung ist möglich"}, {"text": "Nein", "correct": false, "because": "Flexibilität ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine zeitliche Befristung?', 3, '[{"text": "Softwareentwicklung mit Deadline", "correct": true, "because": "Hat festes Ende"}, {"text": "Wöchentliche Wartung", "correct": false, "because": "Wiederkehrend"}, {"text": "Unendliches Forschungsvorhaben", "correct": false, "because": "Keine Begrenzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die zeitliche Befristung nur vom Endtermin abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Start und Zwischenziele zählen"}, {"text": "Ja", "correct": false, "because": "Gesamtdauer ist relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente definieren die zeitliche Befristung?', 4, '[{"text": "Projektstart", "correct": true, "because": "Markiert Beginn"}, {"text": "Unbegrenzte Dauer", "correct": false, "because": "Widerspricht Befristung"}, {"text": "Projektende", "correct": true, "because": "Markiert Abschluss"}, {"text": "Flexible Pausen", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein zeitlich befristetes Projekt immer pünktlich enden?', 2, '[{"text": "Nein", "correct": true, "because": "Verschiebungen sind möglich"}, {"text": "Ja", "correct": false, "because": "Realität erlaubt Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft bei der zeitlichen Befristung?', 3, '[{"text": "Gantt-Diagramm", "correct": true, "because": "Visualisiert Zeitplan"}, {"text": "Teamgrößenplanung", "correct": false, "because": "Fokussiert Personen"}, {"text": "Kostenübersicht", "correct": false, "because": "Fokussiert Budget"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Zeitplan zeitlich befristet sein?', 2, '[{"text": "Nein", "correct": true, "because": "Planung definiert Befristung"}, {"text": "Ja", "correct": false, "because": "Zeit braucht Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die zeitliche Befristung im Projektmanagement?', 3, '[{"text": "Setzt Rahmen für Planung", "correct": true, "because": "Strukturiert Ablauf"}, {"text": "Verhindert Teamarbeit", "correct": false, "because": "Unabhängig davon"}, {"text": "Erhöht Budget", "correct": false, "because": "Kosten sind separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zeitliche Befristung erfordert Meilensteine. b) Sie ist unabhängig von Zielen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ziele beeinflussen Zeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn die zeitliche Befristung fehlt?', 3, '[{"text": "Projekt wird zur Daueraufgabe", "correct": true, "because": "Verliert Projektcharakter"}, {"text": "Team wird effizienter", "correct": false, "because": "Fehlende Grenzen stören"}, {"text": "Kosten sinken", "correct": false, "because": "Kosten können steigen"}]');